sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float fps;
uniform float amplitude;
uniform float rotAmp;
uniform float scaleAmp;
uniform float boil;
uniform float seed;
uniform float transparentEdge;
uniform float shutter;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float4 smp(float2 p, float tr) {
    return tr > 0.5 ? texT(p) : tex(p);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float2 hash22(float2 p) {
    return float2(hash21(p), hash21(p + float2(17.31, 5.17)));
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
float4 shot(float2 coord, float T) {
    float f = floor(T * fps);
    float2 r = hash22(float2(f, seed));
    float rr = hash21(float2(f + 9.0, seed));
    float sc = 1.0 + (hash21(float2(f + 4.0, seed + 2.0)) - 0.5) * 2.0 * scaleAmp;
    float2 ctr = size * 0.5;
    float2 q = ctr + rot2(coord - ctr - (r - 0.5) * 2.0 * amplitude, -(rr - 0.5) * 2.0 * radians(rotAmp)) / sc;
    q += (float2(vnoise(coord / 30.0 + f), vnoise(coord / 30.0 + f + 50.0)) - 0.5) * 2.0 * boil;
    return smp(q, transparentEdge);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    for (int i = 0; i < 8; i++) {
        acc += shot(coord, time - shutter * 0.04 * float(i) / 7.0);
    }
    return fin(c, acc / 8.0, opacity);
}
